import{key,createSeason,advance}from'./engine.js';
const files=['Alex.webp','Billy.webp','Catherine.png','demarin.webp','elisa.webp','Eva.png','Evaggelia.png','evelyn.webp','hope.webp','irene.png','Jasmine.png','Luna.webp','pauline.webp','phillip.webp','rino.webp','sargenie.jpeg','smaragda.jpeg','Sorina.png','tony.webp','vicky.jpg','Violet.png','zoe.jpeg'];
const defaults=files.map((f,i)=>({id:'spirit-'+i,name:f.split('.')[0].replace(/^./,c=>c.toUpperCase()),image:'characters/'+f,strategy:5,social:5,competition:5,custom:false}));
let state={players:defaults,selected:defaults.slice(0,12).map(p=>p.id),size:12,relations:{},alliances:[],season:null,sound:false,cinema:true},tab='cast',search='',busy=false,installPrompt=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const selected=()=>state.players.filter(p=>state.selected.includes(p.id));const toast=t=>{const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',3200)};
let db;const ready=new Promise((resolve)=>{const req=indexedDB.open('spirit-house',1);req.onupgradeneeded=()=>req.result.createObjectStore('save');req.onsuccess=()=>{db=req.result;const r=db.transaction('save').objectStore('save').get('game');r.onsuccess=()=>{if(r.result)state=r.result;resolve()};r.onerror=resolve};req.onerror=resolve});
function save(){if(!db){toast('Η αποθήκευση δεν είναι διαθέσιμη σε αυτόν τον browser.');return}const t=db.transaction('save','readwrite');t.objectStore('save').put(structuredClone(state),'game');t.onerror=()=>toast('Δεν υπάρχει αρκετός χώρος για αποθήκευση.');}
const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
function card(p,season=false){const chosen=state.selected.includes(p.id);return `<article class="card ${chosen&&!season?'selected':''} ${p.out?'eliminated':''}"><img class="portrait" src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy">${season?'':`<button class="select" data-toggle="${p.id}" aria-label="${chosen?'Αφαίρεση':'Επιλογή'} ${esc(p.name)}" aria-pressed="${chosen}">${chosen?'✓':'+'}</button>`}<div class="cardbody"><strong>${esc(p.name)}</strong><small>${season?(state.season.winner===p.id?'🏆 Νικητής':p.out?'Αποχώρησε':state.season.hoh===p.id?'Αρχηγός':state.season.nominees.includes(p.id)?'Υποψήφιος':'Μέσα στο σπίτι'):p.custom?'CUSTOM CHARACTER':'SPIRIT CHARACTER'}</small>${season?'':`<button class="edit" data-edit="${p.id}">Ρύθμιση χαρακτήρα ↗</button>`}</div></article>`;}
function render(){const season=state.season;document.body.dataset.mode=season?'live':'setup';app.innerHTML=`<div class="topline"><div><span class="eyebrow">${season?'● LIVE · SPIRIT HOUSE':'ENTER THE HOUSE'}</span><h1>${season?'Το σπίτι βλέπει τα πάντα.':'Η δική σου ιστορία ξεκινά εδώ.'}</h1><p>${season?'Συμμαχίες, μυστικά και μία μόνο θέση στην κορυφή.':'Διάλεξε τους παίκτες. Όρισε τις σχέσεις. Άφησε το παιχνίδι να εξελιχθεί.'}</p></div><div class="toolbar">${btn(state.sound?'♫ Ήχος ενεργός':'♫ Ήχος κλειστός','sound')}${btn(state.cinema?'◉ Cinematic':'▷ Γρήγορη προβολή','cinema')}</div></div>${season?seasonView():`<nav class="tabs" aria-label="Ρυθμίσεις σεζόν">${[['cast','01 Παίκτες'],['relations','02 Σχέσεις'],['alliances','03 Συμμαχίες']].map(([id,label])=>btn(label,'tab-'+id,tab===id?'active':'')).join('')}</nav><div class="workspace"><section>${tab==='cast'?castView():tab==='relations'?relationsView():alliancesView()}</section>${sidebar()}</div>`}<div class="foot">SPIRIT HOUSE · Η πρόοδος αποθηκεύεται με ασφάλεια σε αυτή τη συσκευή.</div>`;bind();}
function castView(){return `<div class="row"><h2>Γνώρισε τους συγκάτοικους</h2><span class="muted">22 Spirits + οι δικοί σου χαρακτήρες</span></div><div class="toolbar"><input id="search" aria-label="Αναζήτηση χαρακτήρα" placeholder="Αναζήτηση χαρακτήρα…" value="${esc(search)}">${btn('⤨ Τυχαία επιλογή','random')}${btn('+ Δικός σου παίκτης','custom')}</div><div class="grid" id="cast-grid">${state.players.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())).map(p=>card(p)).join('')}</div>`;}
function sidebar(){return `<aside class="panel"><span class="eyebrow">SEASON SETUP</span><h2 style="margin-top:10px">Το cast σου</h2><label for="size">Αριθμός παικτών</label><select id="size">${Array.from({length:21},(_,i)=>i+4).map(n=>`<option ${n===state.size?'selected':''}>${n}</option>`).join('')}</select><div class="count">${state.selected.length}<span> / ${state.size}</span></div><div class="progress"><div style="width:${Math.min(100,state.selected.length/state.size*100)}%"></div></div>${selected().slice(0,5).map(p=>`<div class="mini"><img src="${esc(p.image)}" alt="">${esc(p.name)}</div>`).join('')}${selected().length>5?`<p class="muted">+ ${selected().length-5} ακόμα συγκάτοικοι</p>`:''}<button class="primary" data-action="start" ${state.selected.length!==state.size?'disabled':''}>Έναρξη σεζόν ▷</button><p class="muted">${state.selected.length===state.size?'Το σπίτι είναι έτοιμο να ανοίξει.':`Επίλεξε ${state.size-state.selected.length} ακόμα παίκτες.`}</p><details class="help"><summary>Πώς παίζεται;</summary><p>Ο αρχηγός ορίζει δύο υποψηφίους. Το veto μπορεί να σώσει έναν. Οι υπόλοιποι ψηφίζουν ποιος φεύγει. Στους 3, ο τελικός αρχηγός επιλέγει τον αντίπαλό του. Οι τελευταίοι έως 7 αποχωρήσαντες ψηφίζουν τον νικητή. Σε ισοψηφία τελικού γίνεται δοκιμασία νικών και κοινωνικότητας.</p></details></aside>`;}
function options(exclude){return selected().filter(p=>p.id!==exclude).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}
function relationsView(){return `<h2>Φίλοι ή αντίπαλοι;</h2><p>Οι σχέσεις είναι αμοιβαίες και επηρεάζουν υποψηφιότητες, veto και ψήφους. Το 0 είναι ουδέτερο.</p><form id="relation-form" class="relation"><select name="a" aria-label="Πρώτος παίκτης">${options()}</select><select name="b" aria-label="Δεύτερος παίκτης">${selected().map((p,i)=>`<option value="${p.id}" ${i===1?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select name="value" aria-label="Σχέση"><option value="8">Κολλητοί (+8)</option><option value="4">Φίλοι (+4)</option><option value="0">Ουδέτεροι (0)</option><option value="-4">Αντιπάθεια (−4)</option><option value="-8">Εχθροί (−8)</option></select><button>Ορισμός</button></form>${Object.entries(state.relations).filter(([k])=>k.split('|').every(id=>state.selected.includes(id))).map(([k,v])=>`<div class="row alliance"><span>${k.split('|').map(id=>esc(state.players.find(p=>p.id===id).name)).join(' ↔ ')}</span><strong style="color:${v>=0?'#bcf58a':'#fc9094'}">${v>0?'+':''}${v}</strong><button data-delrelation="${k}">Αφαίρεση</button></div>`).join('')||'<p class="empty">Όλοι ξεκινούν με ουδέτερες σχέσεις.</p>'}`;}
function alliancesView(){return `<h2>Ποιοι θα παίξουν μαζί;</h2><p>Δημιούργησε ομάδες με κοινό στόχο. Η αφοσίωση ενισχύει την προστασία μεταξύ μελών, χωρίς να εγγυάται τις αποφάσεις τους.</p><form id="alliance-form" class="alliance"><input name="name" placeholder="Όνομα συμμαχίας" aria-label="Όνομα συμμαχίας" maxlength="40" required><div class="chips">${selected().map(p=>`<label><input type="checkbox" name="member" value="${p.id}"> ${esc(p.name)}</label>`).join('')}</div><label>Αφοσίωση <select name="loyalty"><option value="4">Χαλαρή · 4/10</option><option value="7" selected>Δυνατή · 7/10</option><option value="10">Απόλυτη · 10/10</option></select></label> <button>+ Δημιουργία</button></form>${state.alliances.map((g,i)=>`<div class="alliance"><div class="row"><h2>${esc(g.name)}</h2><button data-delalliance="${i}">Διαγραφή</button></div><p>${g.members.map(id=>esc(state.players.find(p=>p.id===id)?.name||'')).join(' · ')}</p><span class="badge">Αφοσίωση ${g.loyalty}/10</span></div>`).join('')}`;}
function eventView(e){const s=state.season;const get=id=>s.players.find(p=>p.id===id);return `<article class="event ${e.twist?'twist-event':''}"><span class="room-label">${e.twist?'⚡ TWIST ACTIVATED':'SPIRIT HOUSE · LIVE FEED'}</span><span class="eyebrow">ΕΒΔΟΜΑΔΑ ${e.week}</span><h3>${esc(e.title)}</h3><div class="faces">${e.ids.map(id=>`<div class="face ${e.evicted===id?'eliminated':''}"><img src="${esc(get(id).image)}" alt="">${esc(get(id).name)}</div>`).join('')}</div><p>${esc(e.text)}</p>${e.votes?`<details><summary>Αναλυτικές ψήφοι</summary>${e.votes.map(v=>`<p>${esc(get(v.voter).name)} → ${esc(get(v.target).name)}</p>`).join('')}${e.tie?'<p>Ενεργοποιήθηκε ο κανόνας ισοψηφίας.</p>':''}</details>`:''}</article>`;}
function seasonView(){const s=state.season,w=s.players.find(p=>p.id===s.winner),last=s.history.at(-1);const labels={hoh:'Αγώνας αρχηγού',nominate:'Υποψηφιότητες',veto:'Power of Veto',house:'Δωμάτιο μυστικών',evict:'Αποχώρηση',finalcut:'Τελική αποχώρηση',jury:'Μεγάλος τελικός'},stages=[['hoh','Αρχηγός'],['nominate','Υποψήφιοι'],['veto','Veto'],['house','Μυστικά'],['evict','Αποχώρηση']];return `<div class="row seasonbar"><span class="badge">${w?'SEASON COMPLETE':`● LIVE · Εβδομάδα ${s.week} · ${s.players.filter(p=>!p.out).length} παίκτες`}</span><div class="toolbar">${btn('Νέα σεζόν','reset')}${!w?btn('Μέχρι τον τελικό','finish')+btn(`${labels[s.stage]||'Συνέχεια'} ▷`,'next','primary'):''}</div></div>${!w?`<div class="stage-track">${stages.map(([id,label],i)=>`<div class="${s.stage===id?'now':''} ${stages.findIndex(x=>x[0]===s.stage)>i?'done':''}"><i></i><span>${label}</span></div>`).join('')}</div>`:''}${w?`<div class="winner"><span class="eyebrow">THE WINNER OF SPIRIT HOUSE</span><p>🏆</p><img src="${esc(w.image)}" alt="${esc(w.name)}"><h2>${esc(w.name)}</h2><p>${w.wins} νίκες σε αγωνίσματα · Η επιλογή της κριτικής επιτροπής</p></div>`:''}<div class="grid season-grid">${s.players.map(p=>card(p,true)).join('')}</div><div class="row"><h2>${last?'Το τελευταίο επεισόδιο':'Οι πόρτες του σπιτιού άνοιξαν'}</h2><span class="muted">${s.history.length} γεγονότα</span></div>${last?eventView(last):'<div class="event"><span class="room-label">ROOM 00 · ARRIVAL</span><h3>Όλοι ξεκινούν από το μηδέν.</h3><p>Οι συγκάτοικοι γνωρίζονται. Πάτησε «Αγώνας αρχηγού» για την πρώτη δοκιμασία.</p></div>'}${s.history.length>1?`<details><summary>Αρχείο επεισοδίων (${s.history.length-1})</summary>${s.history.slice(0,-1).reverse().map(eventView).join('')}</details>`:''}`;}
function bind(){app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));app.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggle(b.dataset.toggle));app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));app.querySelectorAll('[data-delrelation]').forEach(b=>b.onclick=()=>{delete state.relations[b.dataset.delrelation];save();render()});app.querySelectorAll('[data-delalliance]').forEach(b=>b.onclick=()=>{state.alliances.splice(+b.dataset.delalliance,1);save();render()});const size=app.querySelector('#size');if(size)size.onchange=()=>{state.size=+size.value;state.selected=state.selected.slice(0,state.size);clean();save();render()};const input=app.querySelector('#search');if(input)input.oninput=()=>{search=input.value;const pos=input.selectionStart;render();const n=app.querySelector('#search');n.focus();n.setSelectionRange(pos,pos)};const rf=app.querySelector('#relation-form');if(rf)rf.onsubmit=e=>{e.preventDefault();const f=new FormData(rf);if(f.get('a')===f.get('b')||!f.get('a')||!f.get('b'))return toast('Διάλεξε δύο διαφορετικούς παίκτες.');state.relations[key(f.get('a'),f.get('b'))]=+f.get('value');save();render()};const af=app.querySelector('#alliance-form');if(af)af.onsubmit=e=>{e.preventDefault();const f=new FormData(af),members=f.getAll('member');if(members.length<2)return toast('Μια συμμαχία χρειάζεται τουλάχιστον δύο μέλη.');if(!f.get('name').trim())return;state.alliances.push({name:f.get('name').trim(),members,loyalty:+f.get('loyalty')});save();render()};}
function clean(){state.alliances=state.alliances.map(g=>({...g,members:g.members.filter(id=>state.selected.includes(id))})).filter(g=>g.members.length>1)}
function toggle(id){if(state.selected.includes(id))state.selected=state.selected.filter(x=>x!==id);else if(state.selected.length<state.size)state.selected.push(id);else return toast('Το cast είναι πλήρες. Αφαίρεσε έναν παίκτη ή αύξησε τις θέσεις.');clean();save();render()}
function edit(id){const p=state.players.find(p=>p.id===id)||{id:crypto.randomUUID(),name:'',image:'',strategy:5,social:5,competition:5,custom:true};let img=p.image;modal.innerHTML=`<form id="player-form"><div class="row"><h2>${id?'Ρύθμιση χαρακτήρα':'Ο δικός σου παίκτης'}</h2><button type="button" id="close">✕</button></div>${img?`<img class="preview" src="${esc(img)}" alt="Προεπισκόπηση">`:''}<label for="pname">Όνομα</label><input id="pname" name="name" value="${esc(p.name)}" placeholder="π.χ. Max" required maxlength="30"><label for="photo">Φωτογραφία</label><input id="photo" type="file" accept="image/png,image/jpeg,image/webp"><p class="muted">PNG, JPG ή WebP · έως 10 MB</p>${[['strategy','Στρατηγική'],['social','Κοινωνικότητα'],['competition','Αγωνίσματα']].map(([k,label])=>`<label for="${k}">${label} <output>${p[k]}</output>/10</label><input id="${k}" name="${k}" type="range" min="1" max="10" value="${p[k]}">`).join('')}<p class="muted">Οι τιμές είναι δικές σου επιλογές και επηρεάζουν τις πιθανότητες, όχι βέβαια αποτελέσματα.</p><button class="primary" id="saveplayer">Αποθήκευση χαρακτήρα</button></form>`;modal.showModal();modal.querySelector('#close').onclick=()=>modal.close();modal.querySelectorAll('[type=range]').forEach(r=>r.oninput=()=>r.previousElementSibling.querySelector('output').textContent=r.value);modal.querySelector('#photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)return toast('Η εικόνα πρέπει να είναι έως 10 MB.');const b=modal.querySelector('#saveplayer');b.disabled=true;try{const bitmap=await createImageBitmap(f);const c=document.createElement('canvas');const scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);img=c.toDataURL('image/webp',.85);bitmap.close();let preview=modal.querySelector('.preview');if(!preview){preview=document.createElement('img');preview.className='preview';e.target.after(preview)}preview.src=img;}catch{toast('Δεν ήταν δυνατή η ανάγνωση της εικόνας.')}b.disabled=false;};modal.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;if(!img)return toast('Πρόσθεσε μια φωτογραφία.');const updated={...p,name,image:img,strategy:+f.get('strategy'),social:+f.get('social'),competition:+f.get('competition')};if(id)state.players=state.players.map(x=>x.id===id?updated:x);else{state.players.push(updated);if(state.selected.length<state.size)state.selected.push(p.id)}save();modal.close();render();};}
function tone(final=false){if(!state.sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)();[0,1,2,3].forEach((n)=>{const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=(final?220:110)*[1,1.5,2,3][n];g.gain.setValueAtTime(0,ac.currentTime+n*.18);g.gain.linearRampToValueAtTime(.08,ac.currentTime+n*.18+.04);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+n*.18+1);o.connect(g).connect(ac.destination);o.start(ac.currentTime+n*.18);o.stop(ac.currentTime+n*.18+1.1)});setTimeout(()=>ac.close(),2200)}catch{}}
async function reveal(e){if(!state.cinema)return;busy=true;const s=state.season;const p=s.players.find(p=>p.id===(e.evicted||e.returned||s.winner||e.ids[0]));const overlay=document.createElement('div');overlay.className=`reveal ${e.twist?'twist-reveal':''}`;overlay.innerHTML=`<div class="reveal-glow"></div><div class="scanlines"></div><span class="eyebrow">${e.twist?'⚡ THE HOUSE HAS A SECRET':'SPIRIT HOUSE · LIVE'}</span><h2>${esc(e.title)}</h2><p class="suspense">${e.twist?'Οι κανόνες μόλις άλλαξαν…':e.evicted?'Η απόφαση έχει παρθεί…':s.winner?'Το σπίτι έχει νικητή…':'Η στιγμή της αποκάλυψης…'}</p><div class="reveal-person ${e.evicted?'exit-person':''}"><img src="${esc(p.image)}" alt="${esc(p.name)}"><h1>${esc(p.name)}</h1><span>${e.evicted?'ΑΠΟΧΩΡΕΙ':s.winner?'ΝΙΚΗΤΗΣ ΤΗΣ ΣΕΖΟΝ':e.twist?'ΑΝΑΤΡΟΠΗ':'SPIRIT HOUSE'}</span></div><button class="skip">Συνέχεια ▷</button>`;document.body.append(overlay);tone(!!s.winner||!!e.twist);await new Promise(resolve=>{const timer=setTimeout(resolve,e.twist?5600:4800);overlay.querySelector('button').onclick=()=>{clearTimeout(timer);resolve()}});overlay.classList.add('closing');await new Promise(r=>setTimeout(r,350));overlay.remove();busy=false;}
async function action(a){if(busy)return;if(a.startsWith('tab-')){tab=a.slice(4);render();return}if(a==='sound'){state.sound=!state.sound;save();render();tone();return}if(a==='cinema'){state.cinema=!state.cinema;save();render();return}if(a==='custom')return edit();if(a==='random'){state.selected=[...state.players].sort(()=>Math.random()-.5).slice(0,state.size).map(p=>p.id);clean();save();render();if(state.selected.length<state.size)toast('Πρόσθεσε δικούς σου παίκτες για τις επιπλέον θέσεις.');return}if(a==='start'){if(state.selected.length!==state.size)return;state.season=createSeason(selected(),state.relations,state.alliances);save();render();await reveal({title:'Οι πόρτες ανοίγουν',ids:[state.selected[0]]});return}if(a==='next'){const e=advance(state.season);save();await reveal(e);render();return}if(a==='finish'){modal.innerHTML='<h2>Μετάβαση στον τελικό;</h2><p>Θα προσομοιωθούν όλα τα υπόλοιπα επεισόδια. Θα μπορείς να τα δεις στο αρχείο.</p><div class="row"><button id="cancel">Πίσω</button><button class="primary" id="confirm">Τρέξε τη σεζόν</button></div>';modal.showModal();modal.querySelector('#cancel').onclick=()=>modal.close();modal.querySelector('#confirm').onclick=async()=>{modal.close();let e;while(!state.season.winner)e=advance(state.season);save();await reveal(e);render()};return}if(a==='reset'){modal.innerHTML='<h2>Νέα σεζόν;</h2><p>Η τρέχουσα σεζόν θα αντικατασταθεί. Οι χαρακτήρες και οι αρχικές ρυθμίσεις σου διατηρούνται.</p><div class="row"><button id="cancel">Πίσω</button><button id="confirm" class="primary">Νέα σεζόν</button></div>';modal.showModal();modal.querySelector('#cancel').onclick=()=>modal.close();modal.querySelector('#confirm').onclick=()=>{state.season=null;save();modal.close();render()};}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});document.querySelector('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else{modal.innerHTML='<h2>Εγκατάσταση Spirit House</h2><p>Σε Chrome ή Edge, άνοιξε το μενού και επίλεξε «Εγκατάσταση εφαρμογής». Σε iPhone: Safari → Κοινοποίηση → Προσθήκη στην οθόνη Αφετηρίας.</p><p>Άνοιξε πρώτα την εφαρμογή με σύνδεση για να αποθηκευτούν τα αρχεία για offline παιχνίδι.</p><button id="close">Εντάξει</button>';modal.showModal();modal.querySelector('#close').onclick=()=>modal.close()}};
document.addEventListener('pointermove',e=>{document.documentElement.style.setProperty('--mx',`${e.clientX}px`);document.documentElement.style.setProperty('--my',`${e.clientY}px`)});await ready;render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
